#!/usr/bin/env bash
# Шаг CD «Migrate schema» (DBR-06): накатка схемы отдельным видимым шагом — тот же образ бэкенда,
# root-кред, lore.migrate=true + lore.migrate.only=true; процесс накатывает и выходит.
#
# SPRINT_LORE_MODEL_DOCS_TIDY/MIG-01 (выкатка 1.18 на препрод): на базе, собранной из модели
# (отметка LoreModelSchema, MIG-03), журнала шагов V нет по построению, и накатывать их нельзя —
# они записали бы старую схему поверх новой.
#
# 25.11.2026 (владелец: «доделай из модели и подчисти версионирование»): на базе из модели шаг больше
# НЕ «пропускает»: бэкенд доводит схему до кода (LoreSchemaAdditive — всё, что после 1.18: KnowKind,
# KnowSkill, поля супертегов, посевы скиллов и областей) и печатает строку «… схема собрана из модели
# (LoreModelSchema), шаги V не применяются; доводка схемы кода vN (хэш): типов +…, свойств +…,
# индексов +…, посеяно …» (modelAdditiveLine в LoreSchemaMigrationRunner). Скрипт подтверждает
# накатку только по ней; прежняя строка «шаги V пропущены: накатывать нечего» — красный: это старый
# образ, доводка не выполнялась, и изменения после 1.18 снова тихо не доехали бы.
# На старой базе (журнал шагов V) — прежняя строка «lore.migrate.only=true — схема накатана»
# (доводка идёт там же, после шагов). Ни одной из строк — красный: исход не подтверждён.
#
# Переменные для тестов: MIGRATE_LOG (куда писать лог), MIGRATE_TIMEOUT (секунды, по умолчанию 1800).
set -uo pipefail

LOG="${MIGRATE_LOG:-/tmp/migrate.log}"
rc=0
timeout "${MIGRATE_TIMEOUT:-1800}" docker compose run --rm --no-deps -T lore-backend > "$LOG" 2>&1 || rc=$?
grep -E "LORE MIGRATE|LORE MART|ERROR|Exception" "$LOG" | tail -80 || true

if [ "$rc" != "0" ]; then
  echo "::error::накатка схемы упала (код $rc) — работающий бэкенд НЕ подменён. Хвост лога:"
  tail -60 "$LOG"
  exit 1
fi

line="$(grep -o "схема собрана из модели (LoreModelSchema), шаги V не применяются; доводка схемы кода.*" "$LOG" | tail -1)"
if [ -n "$line" ]; then
  echo "база собрана из модели — шаги V не применяются, схема доведена до кода: ${line#*; }"
  [ -n "${GITHUB_STEP_SUMMARY:-}" ] && echo "- схема: база из модели, ${line#*; }" >> "$GITHUB_STEP_SUMMARY"
  exit 0
fi

if grep -q "схема собрана из модели (LoreModelSchema), шаги V пропущены" "$LOG"; then
  echo "::error::база из модели, а доводки схемы кода нет («шаги V пропущены: накатывать нечего») — образ без LoreSchemaAdditive, изменения схемы после 1.18 не доехали бы"
  exit 1
fi

if ! grep -q "lore.migrate.only=true — схема накатана" "$LOG"; then
  echo "::error::процесс вышел с 0, но строки о завершённой накатке (или о доводке базы из модели) нет — накатка не подтверждена"
  tail -60 "$LOG"
  exit 1
fi
grep -o "доводка схемы кода v.*" "$LOG" | tail -1 | sed 's/^/база шагов V: /' || true
echo "накатка подтверждена"
